"""Exact embedded-graphics ASCII 9x15 menu fonts used by TIliqua UIs."""

from base64 import b64decode

# Source: embedded-graphics fonts/raw/ascii, the same dependency consumed by
# draw::draw_options in XBEAM, OSCIO and SONORO.
_NORMAL_ATLAS = ""
_BOLD_ATLAS = ""

MENU_FONT_CHARS = "".join(chr(code) for code in range(0x20, 0x7f))


def _glyph_rows(encoded):
    atlas = b64decode(encoded)
    atlas_width = 144
    rows = []
    for char_index in range(len(MENU_FONT_CHARS)):
        glyph_x = (char_index % 16) * 9
        glyph_y = (char_index // 16) * 15
        for row in range(15):
            value = 0
            pixel_y = glyph_y + row
            for column in range(9):
                pixel_x = glyph_x + column
                bit_offset = pixel_y * atlas_width + pixel_x
                byte = atlas[bit_offset // 8]
                value = (value << 1) | ((byte >> (7 - bit_offset % 8)) & 1)
            rows.append(value)
    return rows


MENU_FONT_NORMAL = _glyph_rows(_NORMAL_ATLAS)
MENU_FONT_BOLD = _glyph_rows(_BOLD_ATLAS)
MENU_FONT_INIT = MENU_FONT_NORMAL + MENU_FONT_BOLD
